mapper.select:
select t.*,(SELECT u.UNIT_CODE FROM fnd_org_unit u WHERE u.unit_id = t.unit_id)unit_code from jc_funding_execute t
1 = 1
and t.filling_id = #{fillingId}

select t1.* from ( SELECT t.*, ( SELECT sc.meaning value_name FROM sys_code_value_b_v sc WHERE sc. CODE = 'FP.FILL_TYPE' AND sc.code_value = t.fill_type ) FILL_TYPE_N, ( SELECT sc.meaning value_name FROM sys_code_value_b_v sc WHERE sc. CODE = 'FP.FILL_YEAR' AND sc.code_value = t.fill_year ) FILL_YEAR_N, ( SELECT sc.meaning value_name FROM sys_code_value_b_v sc WHERE sc. CODE = 'FP.FILL_QUARTER' AND sc.code_value = t.fill_quarter ) FILL_QUARTER_N, ( SELECT sc.meaning value_name FROM sys_code_value_b_v sc WHERE sc. CODE = 'FP.FILL_MON' AND sc.code_value = t.fill_mon ) FILL_MON_N, ( SELECT sc.meaning value_name FROM sys_code_value_b_v sc WHERE sc. CODE = 'FP.FILL_WEEK' AND sc.code_value = t.fill_week ) FILL_WEEK_N, ( SELECT sc.meaning value_name FROM sys_code_value_b_v sc WHERE sc. CODE = 'FP.FILL_STATUS' AND sc.code_value = t.plan_status ) PLAN_STATUS_N, ( SELECT s.description FROM sys_user s WHERE s.user_id = t.fill_user_id ) FILL_USER_ID_N, ( SELECT u.unit_name FROM fnd_org_unit u WHERE u.unit_id = t.unit_id ) unit_id_n, ( SELECT u.unit_code FROM fnd_org_unit u WHERE u.unit_id = t.unit_id ) unit_code, ( SELECT sc.meaning value_name FROM sys_code_value_b_v sc WHERE sc. CODE = 'EXCUTE_DIMENSION' AND sc.code_value = t.DIMENSION_TYPE ) DIMENSION_TYPE_n, ( SELECT sc.meaning value_name FROM sys_code_value_b_v sc WHERE sc. CODE = 'FP.CONFIRM_STATUS' AND sc.code_value = t.CONFIRM_STATUS ) CONFIRM_STATUS_n FROM jc_funding_execute t )t1
1 = 1
and t1.filling_id = #{fillingId}
and t1.excute_id = #{excuteId}
and t1.fill_type = #{fillType}
and t1.fill_year = #{fillYear}
and t1.fill_quarter = #{fillQuarter}
and t1.fill_week = #{fillWeek}
and t1.fill_mon = #{fillMon}
and (t1.unit_id = #{unitId} or EXISTS (SELECT 1 FROM sys_user U LEFT JOIN SYS_USER_ALLOCATION UR ON UR.USER_ID = U.USER_ID LEFT JOIN SYS_ROLE_B R ON R.ROLE_ID = UR.ROLE_ID WHERE R.ROLE_CODE = 'ADMIN' and U.USER_ID = #{createdBy}) )
and t1.fill_user_id_n = #{fillUserIdN}
and t1.confirm_status = #{confirmStatus}
and t1.dimension_type = #{dimensionType}

select t1.* from ( SELECT t.*, ( SELECT sc.meaning value_name FROM sys_code_value_b_v sc WHERE sc. CODE = 'FP.FILL_TYPE' AND sc.code_value = t.fill_type ) FILL_TYPE_N, ( SELECT sc.meaning value_name FROM sys_code_value_b_v sc WHERE sc. CODE = 'FP.FILL_YEAR' AND sc.code_value = t.fill_year ) FILL_YEAR_N, ( SELECT sc.meaning value_name FROM sys_code_value_b_v sc WHERE sc. CODE = 'FP.FILL_QUARTER' AND sc.code_value = t.fill_quarter ) FILL_QUARTER_N, ( SELECT sc.meaning value_name FROM sys_code_value_b_v sc WHERE sc. CODE = 'FP.FILL_MON' AND sc.code_value = t.fill_mon ) FILL_MON_N, ( SELECT sc.meaning value_name FROM sys_code_value_b_v sc WHERE sc. CODE = 'FP.FILL_WEEK' AND sc.code_value = t.fill_week ) FILL_WEEK_N, ( SELECT sc.meaning value_name FROM sys_code_value_b_v sc WHERE sc. CODE = 'FP.FILL_STATUS' AND sc.code_value = t.plan_status ) PLAN_STATUS_N, ( SELECT s.description FROM sys_user s WHERE s.user_id = t.fill_user_id ) FILL_USER_ID_N, ( SELECT u.unit_name FROM fnd_org_unit u WHERE u.unit_id = t.unit_id ) unit_id_n, ( SELECT u.unit_code FROM fnd_org_unit u WHERE u.unit_id = t.unit_id ) unit_code, ( SELECT sc.meaning value_name FROM sys_code_value_b_v sc WHERE sc. CODE = 'EXCUTE_DIMENSION' AND sc.code_value = t.DIMENSION_TYPE ) DIMENSION_TYPE_n, ( SELECT sc.meaning value_name FROM sys_code_value_b_v sc WHERE sc. CODE = 'FP.CONFIRM_STATUS' AND sc.code_value = t.CONFIRM_STATUS ) CONFIRM_STATUS_n FROM jc_funding_execute t )t1
1 = 1
and t1.filling_id = #{fillingId}
and t1.excute_id = #{excuteId}
and t1.fill_type = #{fillType}
and t1.fill_year = #{fillYear}
and t1.fill_quarter = #{fillQuarter}
and t1.fill_week = #{fillWeek}
and t1.fill_mon = #{fillMon}
